import yaml,glob
live={}
for f in glob.glob('.archon-horizon/tasks/items/*.yaml'):
    d=yaml.safe_load(open(f))
    if d.get('status')=='running':
        for r in d.get('roadmap_refs') or []: live.setdefault(r,[]).append(d['id'])
act=[]
items={}
for f in glob.glob('.archon-horizon/roadmap/items/*.yaml'):
    d=yaml.safe_load(open(f)); items[d['id']]=d
    if d.get('status')=='active': act.append(d['id'])
for a in sorted(act):
    direct=live.get(a)
    # descendant held by live lane?
    desc=[r for r in live if r.startswith(a+'.')]
    print(('HELD  ' if direct else ('ANCEST' if desc else 'ORPHAN')), a, '| direct=',direct,'| live descendants=',sorted(set(sum((live[r] for r in desc),[]))) if desc else [])
"

